// Pseudo: compute per-tenant exposure weights
function computeWeights(tenants){
  const eps = 0.01;
  const sum = tenants.reduce((a,t)=>a+(t.ckne+eps),0);
  return tenants.map(t=>({tenant:t.id, weight:(t.ckne+eps)/sum}));
}
```

